SysDataModelXML.SQLScript:
#LINKSCRIPTGET@DATAQA:
DECLARE @P1 VARCHAR(30) = '{0}';
DECLARE @P2 VARCHAR(30) = '{1}';
DECLARE @T1  VARCHAR(30) ;
DECLARE @T2  VARCHAR(30) ;
DECLARE @N1  INT ;
DECLARE @N2  INT ;
SELECT @T1=ROUTYP  FROM [QAROU] WHERE ROUCOD=@P1
SELECT @T2=MAX(ROUTYP),@N1=COUNT(*)  FROM [QAROU] WHERE ROUCOD=@P2
SELECT  @N2=COUNT(*) FROM  [QAROULIN] WHERE  ROUCOD=@P1


SELECT CASE  WHEN @T1<>@T2 THEN 'LINKPREVENT:Copy ROUTING Code does not belong to this type:'+@T1
             WHEN @P2=''  THEN 'LINKPREVENT:Copy ROUTING Code cannot be empty'
			 WHEN @N1=0  AND @P2<>'' THEN 'LINKPREVENT:Copy ROUTING Code does not exist or spelled incorrectly'
			 WHEN @N2<>0 AND @P2<>'' AND @T1=@T2 THEN 'LINKCONFIRM:Copy ROUTING Code will overwrite the existing data'
			 ELSE ''
END
#
